package com.bank.txn.db;

import com.bank.txn.model.Account;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Mimics JDBC semantics: autoCommit on = each change final immediately.
public class BankConnection {
    private static final Logger log = Logger.getLogger(BankConnection.class.getName());
    private final Map<String, BigDecimal> committed = new HashMap<>();
    private final Map<String, BigDecimal> pending = new HashMap<>();
    private boolean autoCommit = true;

    public BankConnection(Account... seed) { for (Account a : seed) committed.put(a.getAccountId(), a.getBalance()); }

    public void setAutoCommit(boolean v) { this.autoCommit = v; log.info("setAutoCommit(" + v + ")"); }

    public void update(String id, BigDecimal delta) {
        BigDecimal base = pending.getOrDefault(id, committed.get(id));
        pending.put(id, base.add(delta));
        if (autoCommit) commit();   // each statement finalises itself
    }

    public void commit() { committed.putAll(pending); pending.clear(); log.info("COMMIT"); }
    public void rollback() { pending.clear(); log.warning("ROLLBACK — pending discarded"); }
    public BigDecimal balance(String id) { return committed.get(id); }
}
