package com.bank.txn.service;

import com.bank.txn.db.BankConnection;
import java.math.BigDecimal;
import java.util.logging.*;

public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    // BROKEN: autocommit finalises the debit before the credit fails.
    public void brokenTransfer(BankConnection c, String from, String to, BigDecimal amt, boolean failCredit) {
        c.setAutoCommit(true);
        c.update(from, amt.negate());                 // debit — committed immediately
        if (failCredit) { log.severe("credit failed AFTER debit already committed!"); return; }
        c.update(to, amt);
    }

    // CORRECT: explicit transaction makes debit+credit all-or-nothing.
    public void safeTransfer(BankConnection c, String from, String to, BigDecimal amt, boolean failCredit) {
        c.setAutoCommit(false);
        try {
            c.update(from, amt.negate());
            if (failCredit) throw new IllegalStateException("credit step failed");
            c.update(to, amt);
            c.commit();
            log.info(() -> "Transfer Rs." + amt + " " + from + "→" + to + " COMMITTED");
        } catch (RuntimeException ex) {
            c.rollback();
            log.log(Level.SEVERE, "Transfer rolled back, balances unchanged", ex);
        }
    }
}
