package com.bank.txn;

import com.bank.txn.db.BankConnection;
import com.bank.txn.model.Account;
import com.bank.txn.service.TransferService;
import java.math.BigDecimal;
import java.util.logging.*;

public class TxnDemo {
    private static final Logger log = Logger.getLogger(TxnDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        TransferService svc = new TransferService();

        log.info("=== Broken path: autocommit + failing credit ===");
        BankConnection c1 = new BankConnection(
                new Account("SAV2001", new BigDecimal("1000000")),
                new Account("CUR3001", new BigDecimal("250000")));
        svc.brokenTransfer(c1, "SAV2001", "CUR3001", new BigDecimal("50000"), true);
        log.info("SAV2001=" + c1.balance("SAV2001") + " CUR3001=" + c1.balance("CUR3001") + " (money lost!)");

        log.info("=== Correct path: explicit transaction + failing credit ===");
        BankConnection c2 = new BankConnection(
                new Account("SAV2001", new BigDecimal("1000000")),
                new Account("CUR3001", new BigDecimal("250000")));
        svc.safeTransfer(c2, "SAV2001", "CUR3001", new BigDecimal("50000"), true);
        log.info("SAV2001=" + c2.balance("SAV2001") + " CUR3001=" + c2.balance("CUR3001") + " (unchanged)");

        log.info("=== Correct path: explicit transaction + success ===");
        svc.safeTransfer(c2, "SAV2001", "CUR3001", new BigDecimal("50000"), false);
        log.info("SAV2001=" + c2.balance("SAV2001") + " CUR3001=" + c2.balance("CUR3001"));
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

